using HRM.Models;using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace HRM.Api.Data.EntityConfigurations;
public sealed class RecruitmentAssessmentsMapping:IEntityTypeConfiguration<RecruitmentAssessment>,IEntityTypeConfiguration<RecruitmentPanelScorecard>{public void Configure(EntityTypeBuilder<RecruitmentAssessment>b){b.ToTable("RM_RecruitmentAssessments");b.HasKey(x=>x.Id);b.Property(x=>x.Type).HasMaxLength(30).IsRequired();b.Property(x=>x.TemplateCode).HasMaxLength(100).IsRequired();b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentVacancyId,x.ScheduledAtUtc});b.HasOne<RecruitmentVacancy>().WithMany().HasForeignKey(x=>x.RecruitmentVacancyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}public void Configure(EntityTypeBuilder<RecruitmentPanelScorecard>b){b.ToTable("RM_RecruitmentPanelScorecards");b.HasKey(x=>x.Id);b.Property(x=>x.TotalScore).HasPrecision(8,2);b.Property(x=>x.CriterionScoresJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentAssessmentId,x.RecruitmentApplicationId,x.ScorerUserId}).IsUnique();b.HasOne<RecruitmentAssessment>().WithMany().HasForeignKey(x=>x.RecruitmentAssessmentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<RecruitmentApplication>().WithMany().HasForeignKey(x=>x.RecruitmentApplicationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}}
